public boolean isIsomorphic(String s, String t) {
  Map<Character, Character> ab = new HashMap<>(), ba = new HashMap<>();
  for (int i = 0; i < s.length(); i++) {
    char a = s.charAt(i), b = t.charAt(i);
    if (ab.getOrDefault(a, b) != b || ba.getOrDefault(b, a) != a) return false;
    ab.put(a, b);
    ba.put(b, a);
  }
  return true;
}

public boolean wordPattern(String pattern, String s) {
  String[] w = s.split(" ");
  if (w.length != pattern.length()) return false;
  Map<Character, String> pw = new HashMap<>();
  Map<String, Character> wp = new HashMap<>();
  for (int i = 0; i < w.length; i++) {
    char c = pattern.charAt(i);
    if (pw.containsKey(c) && !pw.get(c).equals(w[i])) return false;
    if (wp.containsKey(w[i]) && wp.get(w[i]) != c) return false;
    pw.put(c, w[i]);
    wp.put(w[i], c);
  }
  return true;
}

