class LRUCache {
  private class Node { int k, v; Node prev, next; Node(int k, int v) { this.k = k; this.v = v; } }
  private final int cap;
  private final Map<Integer, Node> map = new HashMap<>();
  private final Node head = new Node(0, 0), tail = new Node(0, 0);

  public LRUCache(int capacity) { cap = capacity; head.next = tail; tail.prev = head; }

  public int get(int key) {
    Node n = map.get(key);
    if (n == null) return -1;
    remove(n); addFront(n);
    return n.v;
  }

  public void put(int key, int value) {
    Node n = map.get(key);
    if (n != null) { n.v = value; remove(n); addFront(n); return; }
    if (map.size() == cap) { Node lru = tail.prev; remove(lru); map.remove(lru.k); }
    n = new Node(key, value);
    map.put(key, n); addFront(n);
  }

  private void remove(Node n) { n.prev.next = n.next; n.next.prev = n.prev; }
  private void addFront(Node n) { n.next = head.next; n.prev = head; head.next.prev = n; head.next = n; }
}

